from yinshi import runner_agent

_RUNNER_NOISE_PUBLIC_KEY = "REDACTED"


def test_runner_github_access_requires_bearer_token(auth_client: TestClient) -> None:
    """The runner GitHub access endpoint rejects unauthenticated requests."""
    response = auth_client.post(
        "/api/settings/runner/github-access",
        json={"remote_url": "https://github.com/owner/repo.git"},
    )
    assert response.status_code == 401
    assert response.json()["detail"] == "Runner bearer token is required"


def test_runner_github_access_rejects_invalid_bearer_token(auth_client: TestClient) -> None:
    """The runner GitHub access endpoint rejects an invalid runner token."""
    response = auth_client.post(
        "/api/settings/runner/github-access",
        json={"remote_url": "https://github.com/owner/repo.git"},
        headers={"Authorization": "Bearer invalid-token"},
    )
    assert response.status_code == 401
    assert "Runner token is invalid" in response.json()["detail"]


def test_runner_github_access_resolves_for_authenticated_runner(
    auth_client: TestClient,
) -> None:
    """Authenticated runner can resolve anonymous access for a public GitHub repo."""
    create_response = auth_client.post(
        "/api/settings/runner",
        json={"name": "AWS runner", "cloud_provider": "aws", "region": "us-east-1"},
    )
    assert create_response.status_code == 201
    register_response = auth_client.post(
        "/runner/register",
        json={
            "registration_token": create_response.json()["registration_token"],
            "runner_version": "0.1.0",
            "capabilities": {},
            "data_dir": "/var/lib/yinshi",
            "noise_public_key": _RUNNER_NOISE_PUBLIC_KEY,
        },
    )
    assert register_response.status_code == 201
    runner_token = register_response.json()["runner_token"]

    response = auth_client.post(
        "/api/settings/runner/github-access",
        headers={"Authorization": f"Bearer {runner_token}"},
        json={"remote_url": "https://github.com/owner/repo.git"},
    )
    assert response.status_code == 200
    payload = response.json()
    assert payload["clone_url"] == "https://github.com/owner/repo.git"
    assert payload["access_token"] is None
    assert payload["install_id"] is None
    assert payload["repo_install_id"] is None
    assert payload["manage_url"] is None


